function drawSilvallyChimeraGuardian(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 32 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi vây cá lam
  ctx.fillStyle = '#2563eb';
  ctx.beginPath(); ctx.moveTo(14, by + 12); ctx.lineTo(34, by - 8); ctx.lineTo(22, by + 18); ctx.fill();
  ctx.fillStyle = '#cbd5e1';
  ctx.beginPath(); ctx.moveTo(26, by - 2); ctx.lineTo(34, by - 8); ctx.lineTo(36, by + 8); ctx.fill();

  // 3. Thân
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(-2, by + 14, 18 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. Chân
  ctx.fillStyle = '#1e293b';
  [4, 12].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 6, 18, 2); ctx.fill();
  });
  ctx.fillStyle = '#7c3aed';
  ctx.beginPath(); ctx.arc(7,  by + 26, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(15, by + 24, 3, 0, Math.PI * 2); ctx.fill();

  ctx.fillStyle = '#1e293b';
  [-16, -8].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 6, 18, 2); ctx.fill();
  });
  ctx.fillStyle = '#15803d';
  [-13, -5].forEach(x => {
    ctx.beginPath(); ctx.arc(x, by + 34, 4, 0, Math.PI * 2); ctx.fill();
  });

  // 5. Bờm trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-8, by + 6,  12, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0,  by + 4,  10, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-6, by - 4,  13, 0, Math.PI * 2); ctx.fill();

  // 6. Đầu & Lưỡi rìu bạc
  ctx.beginPath(); ctx.arc(-10, by - 12, 10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#cbd5e1';
  ctx.beginPath(); ctx.moveTo(-14, by - 16); ctx.lineTo(-22, by - 40); ctx.lineTo(-4, by - 20); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-6,  by - 20); ctx.lineTo(4,   by - 38); ctx.lineTo(0,   by - 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(2,   by - 18); ctx.lineTo(12,  by - 32); ctx.lineTo(6,   by - 14); ctx.fill();

  // 7. Bánh răng tai & Mỏ
  ctx.fillStyle = '#cbd5e1';
  ctx.beginPath(); ctx.arc(-2, by - 12, 4, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1; ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-16, by - 14); ctx.lineTo(-26, by - 8); ctx.lineTo(-14, by - 6); ctx.fill();

  // 8. Mắt đỏ
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(-12, by - 12, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-13, by - 13, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-14, by - 12); ctx.lineTo(-10, by - 12); ctx.stroke();
  }

  ctx.restore();
}
